package dev.milinktr.regionfix;

final class AppTranslationData {
    private AppTranslationData() {}
    private static final String G = "";
    private static final String W = "";
    static String forPackage(String pkg) {
        if ("com.miui.gallery".equals(pkg)) return G;
        if ("com.miui.weather2".equals(pkg)) return W;
        if ("com.miui.mediaeditor".equals(pkg)) return E;
        if ("com.hyper.gallery.plugin".equals(pkg)) return P;
        return null;
    }
    private static final String E = "";
    private static final String P = "";
}
